class Solution {
    public String countAndSay(int n) {
        String term = "1";
        for (int step = 2; step <= n; step++) {
            term = say(term);
        }
        return term;
    }

    private String say(String term) {
        StringBuilder next = new StringBuilder();
        int index = 0;
        while (index < term.length()) {
            char digit = term.charAt(index);
            int count = 0;
            while (index < term.length() && term.charAt(index) == digit) {
                index++;
                count++;
            }
            next.append(count).append(digit);
        }
        return next.toString();
    }
}

class Solution {
    public String countAndSay(int n) {
        if (n == 1) {
            return "1";
        }
        return describe(countAndSay(n - 1));
    }

    private String describe(String previous) {
        StringBuilder next = new StringBuilder();
        int i = 0;
        while (i < previous.length()) {
            int j = i + 1;
            while (j < previous.length() && previous.charAt(j) == previous.charAt(i)) {
                j++;
            }
            next.append(j - i).append(previous.charAt(i));
            i = j;
        }
        return next.toString();
    }
}

class Solution {
    private static final java.util.regex.Pattern RUN = java.util.regex.Pattern.compile("(.)\\1*");

    public String countAndSay(int n) {
        String term = "1";
        for (int step = 2; step <= n; step++) {
            java.util.regex.Matcher matcher = RUN.matcher(term);
            StringBuilder next = new StringBuilder();
            while (matcher.find()) {
                String run = matcher.group();
                next.append(run.length()).append(run.charAt(0));
            }
            term = next.toString();
        }
        return term;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public String countAndSay(int n) {
        List<Run> runs = new ArrayList<>();
        runs.add(new Run('1', 1));

        for (int step = 2; step <= n; step++) {
            List<Character> spoken = new ArrayList<>();
            for (Run run : runs) {
                String count = Integer.toString(run.count);
                for (int i = 0; i < count.length(); i++) {
                    spoken.add(count.charAt(i));
                }
                spoken.add(run.digit);
            }
            runs = compress(spoken);
        }

        StringBuilder answer = new StringBuilder();
        for (Run run : runs) {
            for (int i = 0; i < run.count; i++) {
                answer.append(run.digit);
            }
        }
        return answer.toString();
    }

    private List<Run> compress(List<Character> chars) {
        List<Run> result = new ArrayList<>();
        int index = 0;
        while (index < chars.size()) {
            char digit = chars.get(index);
            int count = 0;
            while (index < chars.size() && chars.get(index) == digit) {
                index++;
                count++;
            }
            result.add(new Run(digit, count));
        }
        return result;
    }

    private static class Run {
        final char digit;
        final int count;

        Run(char digit, int count) {
            this.digit = digit;
            this.count = count;
        }
    }
}

class Solution {
    private static final String[] CACHE = buildCache();

    public String countAndSay(int n) {
        return CACHE[n];
    }

    private static String[] buildCache() {
        String[] cache = new String[31];
        cache[1] = "1";
        for (int n = 2; n <= 30; n++) {
            cache[n] = say(cache[n - 1]);
        }
        return cache;
    }

    private static String say(String term) {
        StringBuilder next = new StringBuilder();
        int start = 0;
        while (start < term.length()) {
            int end = start + 1;
            while (end < term.length() && term.charAt(end) == term.charAt(start)) {
                end++;
            }
            next.append(end - start).append(term.charAt(start));
            start = end;
        }
        return next.toString();
    }
}
